window.MG_LAZY_DATA["data/lazy/resources/security-v26-039-88cd41e9aab8b5fc.json"]={sha256:"88cd41e9aab8b5fc83328df57629e4379c8fc5cac4a04578fee604037875e335",value:{"sources":[{"id":"v26-case-8b282b9c60ccf648","url":"https://yara.readthedocs.io/en/stable/writingrules.html","title":"YARA: Writing rules","titleEn":"YARA: Writing rules","publisher":"YARA Project","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-039","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-039","related":[{"id":"security-v26-040","referenceUrls":["https://docs.suricata.io/en/suricata-8.0.2/rules/thresholding.html"],"title":"Suricata 門檻：告警抑制與偵測品質","titleEn":"Suricata thresholds: alert suppression and detection quality","why":"用兩課的可觀察驗收條件比較模型邊界：8與16組全部有期望值，沒有下載或執行惡意樣本；報告將規則命中與惡意判定分開。 交付8/16組無害文字fixture規格、真值表與編碼邊界結果。","whyEn":"Compare model boundaries using observable acceptance criteria: Every one of 8 and 16 combinations has an expectation; no malware is downloaded or executed, and matching is distinguished from maliciousness. Deliver specifications for 8/16 inert text fixtures, truth tables and encoding-boundary results.","difference":"以一個來源在固定60秒窗內的12個無害匹配時間點，紙面模擬type threshold每累積N個匹配才告警並重置；與limit、detection_filter分開。","differenceEn":"Use 12 harmless matches from one source within a fixed 60-second window to model type threshold alerting/reset every N matches; distinguish limit and detection_filter.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["m個獨立布林標記有2^m種組合；存在性邏輯、字串邊界與編碼需分別驗證，樣本不可包含可執行惡意內容。 基準有3個標記，每個只計有/無，組合無其他限制。 2^3=8組；加入DELTA後2^4=16組。對至少兩標記條件，三標記版應有4組命中。","在單一視窗、不跨重置邊界的教學序列，threshold告警數=floor(matches/N)；此式不套用其他門檻類型或封鎖動作。 同一來源12次匹配都在單一60秒窗內，N=3，起始計數為0。 floor(12/3)=4次告警；N改4時floor(12/4)=3次。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["m independent Boolean markers give 2^m combinations; test existence logic, word boundaries and encoding separately using no executable malicious content. Baseline has three markers, each present or absent with no other constraints. 2^3=8 combinations; adding DELTA gives 2^4=16. At least two of three should match four combinations.","For this single-window teaching sequence, threshold alerts=floor(matches/N); do not apply the formula to other threshold types or blocking actions. One source has 12 matches in one 60-second window, N=3 and initial count zero. floor(12/3)=4 alerts; N=4 gives floor(12/4)=3.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-049","referenceUrls":["https://csrc.nist.gov/pubs/sp/800/57/pt1/r5/final"],"title":"NIST 金鑰管理：用途分離、輪替與可恢復資料","titleEn":"NIST key management: purpose separation, rotation and recoverability","why":"用兩課的可觀察驗收條件比較模型邊界：8與16組全部有期望值，沒有下載或執行惡意樣本；報告將規則命中與惡意判定分開。 交付8/16組無害文字fixture規格、真值表與編碼邊界結果。","whyEn":"Compare model boundaries using observable acceptance criteria: Every one of 8 and 16 combinations has an expectation; no malware is downloaded or executed, and matching is distinguished from maliciousness. Deliver specifications for 8/16 inert text fixtures, truth tables and encoding-boundary results.","difference":"為教學檔案加密服務分列資料加密金鑰、金鑰加密金鑰、簽章金鑰與測試金鑰；記錄用途、狀態、持有人及到期，不輸出秘密位元。","differenceEn":"Separate data-encryption, key-encryption, signing and test keys for a teaching file service; record purpose, state, owner and expiry without secret bytes.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["m個獨立布林標記有2^m種組合；存在性邏輯、字串邊界與編碼需分別驗證，樣本不可包含可執行惡意內容。 基準有3個標記，每個只計有/無，組合無其他限制。 2^3=8組；加入DELTA後2^4=16組。對至少兩標記條件，三標記版應有4組命中。","包封重包成本近似金鑰數×每次重包時間；重包資料金鑰不等同重加密所有資料，停用與銷毀也有不同可恢復性後果。 教學10000個資料金鑰，每個序列重包2毫秒；忽略排隊、網路與平行化。 10000×2/1000=20秒；金鑰增至15000個後為30秒。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["m independent Boolean markers give 2^m combinations; test existence logic, word boundaries and encoding separately using no executable malicious content. Baseline has three markers, each present or absent with no other constraints. 2^3=8 combinations; adding DELTA gives 2^4=16. At least two of three should match four combinations.","Envelope rewrap cost is approximately key count×per-key rewrap time; rewrapping data keys differs from reencrypting all data, and deactivation differs from destruction. There are 10000 teaching data keys at 2 ms per sequential rewrap, ignoring queueing, network and parallelism. 10000×2/1000=20 seconds; 15000 keys require 30 seconds.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-65223a8c9b41afa5","url":"https://docs.suricata.io/en/suricata-8.0.2/rules/thresholding.html","title":"Suricata 8.0.2 thresholding keywords","titleEn":"Suricata 8.0.2 thresholding keywords","publisher":"OISF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-75713bd1d69725f8","url":"https://csrc.nist.gov/pubs/sp/800/57/pt1/r5/final","title":"NIST SP 800-57 Part 1 Rev. 5: Key Management","titleEn":"NIST SP 800-57 Part 1 Rev. 5: Key Management","publisher":"NIST","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
